object AvoAssert {
    fun assertMax(propertyId: String, property: String, max: Double, value: Double): List<AvoAssertMessage> {
        if (value > max) {
            return listOf(AvoAssertMax(propertyId, "$property has a maximum value of $max but you provided the value $value"))
        } else {
            return emptyList()
        }
    }

