interface AvoEvent {
    val properties: Map<String, AvoDestinationEvent>
    fun buildBaseProperties(): Map<String, Any>
    val eventId: String
    val eventHash: String
    val eventName: String
    fun collectViolations(): List<AvoAssertMessage> {
        return emptyList()
    }
    fun verify(): AvoResult<Unit, AvoVerificationError> {
        val violations = collectViolations()
        return if (violations.isEmpty()) {
            AvoResult.Success(Unit)
        } else {
            AvoResult.Failure(AvoVerificationError(violations.map { it.message }))
        }
    }
}

val AvoEvent.canonicalProperties: Map<String, Any>
    get() = buildBaseProperties()

data class AvoInvokeConfig(
    val actionId: String,
    val branchId: String,
    val schemaId: String,
    val sourceId: String,
    val inspectorApiKey: String? = null
)


object AvoInvoke {
    suspend fun postInvocation(json: JSONObject): Double? {
        return withContext(Dispatchers.IO) {
            try {
                val connection = URL("https://api.avo.app/i").openConnection() as HttpsURLConnection
                connection.requestMethod = "POST"
                connection.doOutput = true
                connection.setRequestProperty("Content-Type", "application/json")

                val writer = OutputStreamWriter(connection.outputStream)
                writer.write(json.toString())
                writer.flush()

                val statusCode = connection.responseCode
                if (statusCode == 200) {
                    BufferedReader(InputStreamReader(connection.inputStream)).use {
                        val response = StringBuffer()
                        var inputLine = it.readLine()
                        while (inputLine != null) {
                            response.append(inputLine)
                            inputLine = it.readLine()
                        }
                        it.close()
                        val json = JSONObject(response.toString())
                        json.getDouble("sa")
                    }
                } else {
                    connection.disconnect()
                    null
                }
            } catch (e: Throwable) {
              null
            }
        }
    }

    var samplingRate = 1.0

    fun invoke(eventId: String, hash: String, messages: List<AvoAssertMessage>, config: AvoInvokeConfig) {
        if (samplingRate > 0) {
            if (Math.random() < samplingRate) {
                val json = JSONObject()
                json.put("ac", config.actionId)
                json.put("br", config.branchId)
                json.put("en", "dev")
                json.put("ev", eventId)
                json.put("ha", hash)
                json.put("sc", config.schemaId)
                json.put("se", toISO8601UTC(Date()))
                json.put("so", config.sourceId)
                json.put("va", messages.isEmpty())
                json.put("or", "event")

                val me = JSONArray()
                for (message in messages) {
                    val obj = JSONObject()
                    when (message) {
                        is AvoAssertMax -> {
                            obj.put("tag", "expectedMax")
                            obj.put("propertyId", message.propertyId)
                        }
                        is AvoAssertMin -> {
                            obj.put("tag", "expectedMin")
                            obj.put("propertyId", message.propertyId)
                        }
                    }
                    me.put(obj)
                }
                json.put("me", me)

                CoroutineScope(SupervisorJob() + Dispatchers.Main).launch {
                    postInvocation(json)?.let {
                        samplingRate = it
                    }
                }
            }
        }
    }
    fun invokeMeta(type: String, messages: List<AvoAssertMessage>, config: AvoInvokeConfig) {
        if (samplingRate > 0) {
            if (Math.random() < samplingRate) {
                val json = JSONObject()
                json.put("ac", config.actionId)
                json.put("br", config.branchId)
                json.put("en", "dev")
                json.put("ty", type)
                json.put("sc", config.schemaId)
                json.put("se", toISO8601UTC(Date()))
                json.put("so", config.sourceId)
                json.put("va", messages.isEmpty())
                json.put("me", JSONArray())

                CoroutineScope(SupervisorJob() + Dispatchers.Main).launch {
                    postInvocation(json)?.let {
                        samplingRate = it
                    }
                }
            }
        }
    }

    fun toISO8601UTC(date: Date): String {
        val tz = TimeZone.getTimeZone("UTC")
        val df = SimpleDateFormat("yyyy-MM-dd'T'HH:mm'Z'", Locale.US)
        df.timeZone = tz
        return df.format(date)
    }
}

class Avo(
    env: AvoEnv,
    config: AvoInvokeConfig,
    inspector: Any? = null,
    strict: Boolean = true,
    noop: Boolean = false
) {
    var __STRICT__: Boolean = strict
    var __ENV__: AvoEnv = env
    var __NOOP__: Boolean = noop
    private var __INSPECTOR__: Any? = null
    private val config: AvoInvokeConfig = config

    @SuppressLint("LogNotTimber")
    private var __LOGGER__: (String) -> Unit = { message ->
        Log.d("AvoLogger", message)
    }

    init {
        if (__NOOP__ && __ENV__ == AvoEnv.PROD) {
            Log.w("avo", "[avo] WARNING: Avo cannot be initialized in noop mode in production. Overwriting with noop=false.")
            __NOOP__ = false
        }
        if (__NOOP__) {
            Log.w("avo", "[avo] Avo is now initialized in noop mode. No events will be sent.")
        }

        if (!__NOOP__) {
            this.__INSPECTOR__ = inspector
            if (inspector != null) {
                config.inspectorApiKey?.let { apiKey ->
                    try {
                        val inspectorClass = inspector.javaClass
                        val initMethod = inspectorClass.getDeclaredMethod("init", String::class.java, Int::class.java)
                        initMethod.isAccessible = true
                        when (__ENV__) {
                            AvoEnv.PROD -> initMethod.invoke(inspector, apiKey, 0)
                            AvoEnv.STAGING -> initMethod.invoke(inspector, apiKey, 2)
                            else -> initMethod.invoke(inspector, apiKey, 1)
                        }
                    } catch (e: Exception) {
                        Log.e("avo", "[avo] Error! Included Avo Inspector version does not support the latest features used in Avo functions. Please update your Avo Inspector to the latest version.")
                    }
                }
            }
        }

        if (!__NOOP__ && __ENV__ != AvoEnv.PROD) {
            AvoInvoke.invokeMeta("init", emptyList(), config)
        }
    }

    companion object

    fun setAvoLogger(logger: (String) -> Unit) {
        __LOGGER__ = logger
    }

    /**
     * Processes the event and returns per-destination event data.
     * Call event.verify() before this method to check for missing
     * system properties or validation violations.
     * Returns empty map in noop mode.
     */
    fun process(event: AvoEvent): Map<String, AvoDestinationEvent> {
        if (__NOOP__) {
            return emptyMap()
        }

        if (__ENV__ != AvoEnv.PROD) {
            val violations = event.collectViolations()

            AvoInvoke.invoke(event.eventId, event.eventHash, violations, config = config)

            if (violations.isNotEmpty()) {
                if (__STRICT__) {
                    throw AvoVerificationError(violations.map { it.message })
                } else {
                    Log.w("avo", "[avo] Verification failed: " + violations.joinToString(", ") { it.message })
                }
            }
        }

        val eventProperties = event.properties

        if (eventProperties.isEmpty()) {
            Log.w("avo", "[avo] Warning: Event has no destination properties, skipping")
            return emptyMap()
        }

        this.__INSPECTOR__?.let { inspector ->
            try {
                val inspectorMethod = inspector.javaClass.getDeclaredMethod("avoFunctionTrackSchemaFromEvent",
                    String::class.java, Map::class.java, String::class.java, String::class.java)
                inspectorMethod.isAccessible = true
                val inspectorProperties = event.canonicalProperties.toMutableMap()
                inspectorProperties["avoFunctionEventId"] = event.eventId
                inspectorProperties["avoFunctionEventHash"] = event.eventHash
                inspectorMethod.invoke(inspector, event.eventName, inspectorProperties, event.eventId, event.eventHash)
            } catch (e: Exception) {
                Log.w("avo", "Included Avo Inspector version does not support the latest features used in Avo functions. Please update your Avo Inspector to the latest version.")
            }
        }

        return eventProperties
    }

    fun sendToInspector(event: AvoEvent) {
        this.__INSPECTOR__?.let { inspector ->
            try {
                val inspectorMethod = inspector.javaClass.getDeclaredMethod("avoFunctionTrackSchemaFromEvent",
                    String::class.java, Map::class.java, String::class.java, String::class.java)
                inspectorMethod.isAccessible = true
                val inspectorProperties = event.canonicalProperties.toMutableMap()
                inspectorProperties["avoFunctionEventId"] = event.eventId
                inspectorProperties["avoFunctionEventHash"] = event.eventHash
                inspectorMethod.invoke(inspector, event.eventName, inspectorProperties, event.eventId, event.eventHash)
            } catch (e: Exception) {
                Log.w("avo", "Included Avo Inspector version does not support the latest features used in Avo functions. Please update your Avo Inspector to the latest version.")
            }
        }
    }
